select s.id,seed.category_key,'typed_single','classic_trivia',jsonb_build_object('en',seed.prompt),jsonb_build_object('en',seed.clue),jsonb_build_object('accepted',seed.accepted),jsonb_build_object('en',seed.display),case when seed.percentile<.25 then -1.3 when seed.percentile<.5 then -.3 when seed.percentile<.75 then .7 else 1.5 end,seed.percentile,seed.percentile,0,1,0,'verified',editorial.id,seed.source_url,seed.source_title,encode(extensions.digest(seed.prompt,'sha256'),'hex'),now(),true
